#include "compositor.h"
static int32_t max_i32(int32_t a,int32_t b){return a>b?a:b;}
static int32_t min_i32(int32_t a,int32_t b){return a<b?a:b;}
static int valid(const struct pros_gfx_surface*s){return s&&s->pixels&&s->width&&s->height&&s->stride>=s->width&&((uint64_t)s->stride*s->height<=UINT64_MAX/4u);}
static int rv(const struct pros_gfx_rect*r){return r&&r->width&&r->height;}
int pros_gfx_surface_init(struct pros_gfx_surface*s,uint32_t*p,uint32_t w,uint32_t h,uint32_t st){if(!s||!p||!w||!h||st<w||((uint64_t)st*h>UINT64_MAX/4u))return -1;s->pixels=p;s->width=w;s->height=h;s->stride=st;return 0;}
static struct pros_gfx_rect wr(const struct pros_gfx_window*w){struct pros_gfx_rect r={w->x,w->y,w->surface.width,w->surface.height};return r;}
static int inter(const struct pros_gfx_rect*a,const struct pros_gfx_rect*b,struct pros_gfx_rect*o){int64_t ax1=(int64_t)a->x+(int64_t)a->width,ay1=(int64_t)a->y+(int64_t)a->height,bx1=(int64_t)b->x+(int64_t)b->width,by1=(int64_t)b->y+(int64_t)b->height;int64_t x0=max_i32(a->x,b->x),y0=max_i32(a->y,b->y),x1=ax1<bx1?ax1:bx1,y1=ay1<by1?ay1:by1;if(x1<=x0||y1<=y0)return 0;o->x=(int32_t)x0;o->y=(int32_t)y0;o->width=(uint32_t)(x1-x0);o->height=(uint32_t)(y1-y0);return 1;}
static uint32_t blend(uint32_t d,uint32_t s,uint32_t op){uint32_t sa=((s>>24)&255u)*op/255u,sr=(s>>16)&255u,sg=(s>>8)&255u,sb=s&255u,da=(d>>24)&255u,dr=(d>>16)&255u,dg=(d>>8)&255u,db=d&255u,iv=255u-sa,oa=sa+(da*iv+127u)/255u,or_=(sr*sa+dr*iv+127u)/255u,og=(sg*sa+dg*iv+127u)/255u,ob=(sb*sa+db*iv+127u)/255u;return(oa<<24)|(or_<<16)|(og<<8)|ob;}
int pros_compositor_init(struct pros_compositor*c,struct pros_gfx_surface*t){if(!c||!valid(t))return -1;c->target=*t;c->window_count=0;c->damage_count=0;c->bound=1;return 0;}
int pros_compositor_damage(struct pros_compositor*c,struct pros_gfx_rect r){struct pros_gfx_rect b={0,0,c?c->target.width:0,c?c->target.height:0},q;if(!c||!c->bound||!rv(&r))return -1;if(!inter(&r,&b,&q))return 0;if(c->damage_count>=PROS_COMPOSITOR_MAX_DAMAGE){struct pros_gfx_rect *last=&c->damage[PROS_COMPOSITOR_MAX_DAMAGE-1u];int64_t x0=last->x<q.x?last->x:q.x,y0=last->y<q.y?last->y:q.y,x1=(int64_t)last->x+last->width>(int64_t)q.x+q.width?(int64_t)last->x+last->width:(int64_t)q.x+q.width,y1=(int64_t)last->y+last->height>(int64_t)q.y+q.height?(int64_t)last->y+last->height:(int64_t)q.y+q.height;last->x=(int32_t)x0;last->y=(int32_t)y0;last->width=(uint32_t)(x1-x0);last->height=(uint32_t)(y1-y0);return 0;}c->damage[c->damage_count++]=q;return 0;}
int pros_compositor_add_window(struct pros_compositor*c,const struct pros_gfx_window*w){if(!c||!c->bound||!w||!valid(&w->surface)||c->window_count>=PROS_COMPOSITOR_MAX_WINDOWS)return -1;c->windows[c->window_count]=*w;c->windows[c->window_count].visible=w->visible?1u:0u;if(pros_compositor_damage(c,wr(w))<0)return -2;c->window_count++;return(int)c->window_count-1;}
int pros_compositor_remove_window(struct pros_compositor*c,uint32_t i){if(!c||i>=c->window_count)return -1;(void)pros_compositor_damage(c,wr(&c->windows[i]));for(uint32_t j=i+1;j<c->window_count;j++)c->windows[j-1]=c->windows[j];c->window_count--;return 0;}
int pros_compositor_move_window(struct pros_compositor*c,uint32_t i,int32_t x,int32_t y){if(!c||i>=c->window_count)return -1;(void)pros_compositor_damage(c,wr(&c->windows[i]));c->windows[i].x=x;c->windows[i].y=y;(void)pros_compositor_damage(c,wr(&c->windows[i]));return 0;}
int pros_compositor_set_window_state(struct pros_compositor*c,uint32_t i,uint8_t v,uint8_t op){if(!c||i>=c->window_count)return -1;(void)pros_compositor_damage(c,wr(&c->windows[i]));c->windows[i].visible=v?1u:0u;c->windows[i].opacity=op;(void)pros_compositor_damage(c,wr(&c->windows[i]));return 0;}
static void clear(struct pros_compositor*c,struct pros_gfx_rect r){for(uint32_t y=0;y<r.height;y++){uint32_t*row=c->target.pixels+(uint32_t)(r.y+(int32_t)y)*c->target.stride+(uint32_t)r.x;for(uint32_t x=0;x<r.width;x++)row[x]=0xff000000u;}}
static void draw(struct pros_compositor*c,const struct pros_gfx_window*w,struct pros_gfx_rect d){struct pros_gfx_rect clip; if(!w->visible||!w->opacity||!inter(&wr(w),&d,&clip))return;for(uint32_t y=0;y<clip.height;y++){uint32_t*dst=c->target.pixels+(uint32_t)(clip.y+(int32_t)y)*c->target.stride+(uint32_t)clip.x;const uint32_t*src=w->surface.pixels+(uint32_t)(clip.y-w->y+(int32_t)y)*w->surface.stride+(uint32_t)(clip.x-w->x);for(uint32_t x=0;x<clip.width;x++)dst[x]=blend(dst[x],src[x],w->opacity);}}
static void sort(struct pros_compositor*c){for(uint32_t i=1;i<c->window_count;i++){struct pros_gfx_window k=c->windows[i];uint32_t j=i;while(j&&c->windows[j-1].z>k.z){c->windows[j]=c->windows[j-1];--j;}c->windows[j]=k;}}
int pros_compositor_compose(struct pros_compositor*c){if(!c||!c->bound)return -1;sort(c);for(uint32_t d=0;d<c->damage_count;d++){clear(c,c->damage[d]);for(uint32_t i=0;i<c->window_count;i++)draw(c,&c->windows[i],c->damage[d]);}c->damage_count=0;return 0;}
int pros_compositor_self_test(void){uint32_t tp[16]={0},bp[4]={0xff00ff00u,0xff00ff00u,0xff00ff00u,0xff00ff00u},rp[4]={0x80ff0000u,0x80ff0000u,0x80ff0000u,0x80ff0000u};struct pros_gfx_surface t,b,r;struct pros_compositor c;struct pros_gfx_window w0={0},w1={0};if(pros_gfx_surface_init(&t,tp,4,4,4)||pros_gfx_surface_init(&b,bp,2,2,2)||pros_gfx_surface_init(&r,rp,2,2,2)||pros_compositor_init(&c,&t))return -1;w0.surface=b;w0.z=1;w0.opacity=255;w0.visible=1;w1.surface=r;w1.z=2;w1.opacity=255;w1.visible=1;if(pros_compositor_add_window(&c,&w0)<0||pros_compositor_add_window(&c,&w1)<0||pros_compositor_compose(&c)!=0)return -2;return(tp[0]==0xff807f00u&&tp[3]==0xff807f00u&&tp[4]==0xff807f00u)?0:-3;}
